package edu.ankara.audiometer.application;
import edu.ankara.audiometer.domain.algorithm.TestStateReducer;import edu.ankara.audiometer.domain.model.*;import java.util.*;
public final class SimulationService { private final Map<String,IntensityDbHL> thresholds=new HashMap<>(); public void setThreshold(Ear e, FrequencyHz f, IntensityDbHL t){thresholds.put(key(e,f),t);} public IntensityDbHL thresholdFor(Ear e, FrequencyHz f){return thresholds.getOrDefault(key(e,f),new IntensityDbHL(e==Ear.RIGHT?25:30));} public TestState autoRespond(TestState s){ boolean heard=s.currentIntensity().value()>=thresholdFor(s.currentEar(),s.currentFrequency()).value(); return TestStateReducer.updateState(s, heard?new ProtocolEvent.Response():new ProtocolEvent.NoResponse()); } private static String key(Ear e, FrequencyHz f){return e+":"+f.value();} }
